err=$(bash src/free.sh aoi 2>&1 >/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "one argument exit $rc, expected 2"; fail=1; }
[ "$err" = 'usage: free.sh ROOM DATE' ] || { echo "one argument usage message: $err"; fail=1; }
[ "$(BOOKINGS=$t bash src/free.sh aoi 2026-01-06 | tr '\n' ' ')" = '09:00-18:00 ' ] || { echo "free day with no bookings"; fail=1; }

